import { test, expect } from "vitest";
import { createHmac } from "node:crypto";
import { verifyToken } from "../src/auth/jwt";

const b = (o: object) => Buffer.from(JSON.stringify(o)).toString("base64url");
const sign = (h: object, p: object, s: string) => {
  const d = `${b(h)}.${b(p)}`;
  return `${d}.${createHmac("sha256", s).update(d).digest("base64url")}`;
};
const future = Math.floor(Date.now() / 1000) + 60;

test("valid", () => expect(verifyToken(sign({ alg: "HS256" }, { sub: "u1", exp: future }, "k"), "k")).toEqual({ sub: "u1", exp: future }));
test("wrong secret", () => expect(() => verifyToken(sign({ alg: "HS256" }, { sub: "u1", exp: future }, "k"), "x")).toThrow(/signature/));
test("expired", () => expect(() => verifyToken(sign({ alg: "HS256" }, { sub: "u1", exp: 1 }, "k"), "k")).toThrow(/expired/));
test("alg none", () => expect(() => verifyToken(`${b({ alg: "none" })}.${b({ sub: "u", exp: future })}.`, "k")).toThrow(/algorithm/));
test("tampered payload", () => {
  const t = sign({ alg: "HS256" }, { sub: "u1", exp: future }, "k").split(".");
  t[1] = b({ sub: "admin", exp: future });
  expect(() => verifyToken(t.join("."), "k")).toThrow(/signature/);
});

